(function(){'use strict';const field=document.getElementById('wallet-address'),status=document.getElementById('copy-status');document.getElementById('copy-address').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(field.value);status.textContent='Address copied. Check your token and network before sending.';}catch{field.focus();field.select();status.textContent='Select and copy the address above. Automatic copying is unavailable in this browser.';}});})();
